TYPE ST_AnalogChannel :
STRUCT
    enable         : BOOL;
    hiLIM          : REAL;
    loLIM          : REAL;
    bipolar        : BOOL;
    measuringMode  : INT;
    retVal         : WORD;
    outputValue    : REAL;
END_STRUCT
END_TYPE

FUNCTION_BLOCK FB_AnalogBatchProcessing
VAR_INPUT
    count : DINT;
END_VAR
VAR_IN_OUT
    analogValues : ARRAY[*] OF INT;
    channels     : ARRAY[*] OF ST_AnalogChannel;
END_VAR
VAR_OUTPUT
END_VAR
VAR
END_VAR

edits.old:
FOR tmpIndex := 0 TO (count - 1) DO
    tmpProcessed := FALSE;

    (* Bounds check: skip if index exceeds either array *)
    IF (tmpLower + tmpIndex) > tmpUpperAna OR (tmpLower + tmpIndex) > tmpUpperCh THEN
        CONTINUE;
    END_IF;

    tmpChannel := channels[tmpLower + tmpIndex];

    (* Skip disabled channels; retain previous outputValue and retVal *)
    IF NOT tmpChannel.enable THEN
        CONTINUE;
    END_IF;
